INSERT INTO afl_remaining_21_guard VALUES(1);
INSERT INTO award_definitions (id, code, display_name, nominee_count, eligibility_json, sort_order) SELECT i.id, i.code, i.display_name, i.nominee_count, i.eligibility_json, i.sort_order FROM afl_remaining_21_0 i WHERE NOT EXISTS(SELECT 1 FROM award_definitions t WHERE t.id=i.id);
INSERT INTO award_weights (award_id, settings_version_id, place, points) SELECT i.award_id, i.settings_version_id, i.place, i.points FROM afl_remaining_21_1 i WHERE NOT EXISTS(SELECT 1 FROM award_weights t WHERE t.award_id=i.award_id AND t.settings_version_id=i.settings_version_id AND t.place=i.place);
INSERT INTO award_nominations (id, season_id, award_id, player_id, team_id, nomination_order, selection_source, ai_job_id, nominated_at) SELECT i.id, i.season_id, i.award_id, i.player_id, i.team_id, i.nomination_order, i.selection_source, i.ai_job_id, i.nominated_at FROM afl_remaining_21_2 i WHERE NOT EXISTS(SELECT 1 FROM award_nominations t WHERE t.id=i.id);
INSERT INTO award_vote_runs (id, season_id, award_id, settings_version_id, status, expected_ballots, completed_ballots, ai_job_id, started_at, completed_at) SELECT i.id, i.season_id, i.award_id, i.settings_version_id, i.status, i.expected_ballots, i.completed_ballots, i.ai_job_id, i.started_at, i.completed_at FROM afl_remaining_21_3 i WHERE NOT EXISTS(SELECT 1 FROM award_vote_runs t WHERE t.id=i.id);
INSERT INTO honor_slots (id, season_id, division_id, side, slot_number, position_label, sort_order) SELECT i.id, i.season_id, i.division_id, i.side, i.slot_number, i.position_label, i.sort_order FROM afl_remaining_21_4 i WHERE NOT EXISTS(SELECT 1 FROM honor_slots t WHERE t.id=i.id);
INSERT INTO honor_selections (slot_id, player_id, team_id, selection_source, ai_job_id, selected_at) SELECT i.slot_id, i.player_id, i.team_id, i.selection_source, i.ai_job_id, i.selected_at FROM afl_remaining_21_5 i WHERE NOT EXISTS(SELECT 1 FROM honor_selections t WHERE t.slot_id=i.slot_id);
