-- 21-awards-and-first-teams. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- 18 nominees, 34 honors; three NOT STARTED vote runs; 0 ballots, 0 winners. Exact workbook weights retained.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_21;
CREATE TEMP TABLE afl_remaining_21_0 AS SELECT id, code, display_name, nominee_count, eligibility_json, sort_order FROM award_definitions WHERE 0;
CREATE TEMP TABLE afl_remaining_21_1 AS SELECT award_id, settings_version_id, place, points FROM award_weights WHERE 0;
CREATE TEMP TABLE afl_remaining_21_2 AS SELECT id, season_id, award_id, player_id, team_id, nomination_order, selection_source, ai_job_id, nominated_at FROM award_nominations WHERE 0;
CREATE TEMP TABLE afl_remaining_21_3 AS SELECT id, season_id, award_id, settings_version_id, status, expected_ballots, completed_ballots, ai_job_id, started_at, completed_at FROM award_vote_runs WHERE 0;
CREATE TEMP TABLE afl_remaining_21_4 AS SELECT id, season_id, division_id, side, slot_number, position_label, sort_order FROM honor_slots WHERE 0;
CREATE TEMP TABLE afl_remaining_21_5 AS SELECT slot_id, player_id, team_id, selection_source, ai_job_id, selected_at FROM honor_selections WHERE 0;
CREATE TEMP TABLE afl_remaining_21_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_21_check BEFORE INSERT ON afl_remaining_21_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_0 i JOIN award_definitions t ON t.id=i.id WHERE t.code IS NOT i.code OR t.display_name IS NOT i.display_name OR t.nominee_count IS NOT i.nominee_count OR t.eligibility_json IS NOT i.eligibility_json OR t.sort_order IS NOT i.sort_order) THEN RAISE(ROLLBACK,'award_definitions: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_0 i JOIN award_definitions t ON t.code=i.code WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'award_definitions: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_1 i JOIN award_weights t ON t.award_id=i.award_id AND t.settings_version_id=i.settings_version_id AND t.place=i.place WHERE t.points IS NOT i.points) THEN RAISE(ROLLBACK,'award_weights: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_2 i JOIN award_nominations t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.award_id IS NOT i.award_id OR t.player_id IS NOT i.player_id OR t.team_id IS NOT i.team_id OR t.nomination_order IS NOT i.nomination_order OR t.selection_source IS NOT i.selection_source OR t.ai_job_id IS NOT i.ai_job_id OR t.nominated_at IS NOT i.nominated_at) THEN RAISE(ROLLBACK,'award_nominations: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_2 i JOIN award_nominations t ON t.season_id=i.season_id AND t.award_id=i.award_id AND (t.player_id=i.player_id OR t.nomination_order=i.nomination_order) WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'award_nominations: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_3 i JOIN award_vote_runs t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.award_id IS NOT i.award_id OR t.settings_version_id IS NOT i.settings_version_id OR t.status IS NOT i.status OR t.expected_ballots IS NOT i.expected_ballots OR t.completed_ballots IS NOT i.completed_ballots OR t.ai_job_id IS NOT i.ai_job_id OR t.started_at IS NOT i.started_at OR t.completed_at IS NOT i.completed_at) THEN RAISE(ROLLBACK,'award_vote_runs: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_3 i JOIN award_vote_runs t ON t.season_id=i.season_id AND t.award_id=i.award_id WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'award_vote_runs: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_4 i JOIN honor_slots t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.division_id IS NOT i.division_id OR t.side IS NOT i.side OR t.slot_number IS NOT i.slot_number OR t.position_label IS NOT i.position_label OR t.sort_order IS NOT i.sort_order) THEN RAISE(ROLLBACK,'honor_slots: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_4 i JOIN honor_slots t ON t.season_id=i.season_id AND t.division_id=i.division_id AND t.side=i.side AND t.slot_number=i.slot_number WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'honor_slots: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_21_5 i JOIN honor_selections t ON t.slot_id=i.slot_id WHERE t.player_id IS NOT i.player_id OR t.team_id IS NOT i.team_id OR t.selection_source IS NOT i.selection_source OR t.ai_job_id IS NOT i.ai_job_id OR t.selected_at IS NOT i.selected_at) THEN RAISE(ROLLBACK,'honor_selections: existing record differs; no overwrite.') END;
END;
DROP TRIGGER afl_remaining_21_check;
DROP TABLE afl_remaining_21_guard;
DROP TABLE afl_remaining_21_0;
DROP TABLE afl_remaining_21_1;
DROP TABLE afl_remaining_21_2;
DROP TABLE afl_remaining_21_3;
DROP TABLE afl_remaining_21_4;
DROP TABLE afl_remaining_21_5;
RELEASE SAVEPOINT afl_remaining_21;
PRAGMA foreign_key_check;
SELECT 'award_definitions' AS imported_table,count(*) AS reviewed_records_present FROM award_definitions t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='17f69ed8-4170-572a-bdda-e9c0ff24f987' AND m.target_table='award_definitions' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'award_weights' AS imported_table,count(*) AS reviewed_records_present FROM award_weights t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='17f69ed8-4170-572a-bdda-e9c0ff24f987' AND m.target_table='award_weights' AND m.target_id=CAST(t.award_id AS TEXT)||'|'||CAST(t.settings_version_id AS TEXT)||'|'||CAST(t.place AS TEXT))
UNION ALL
SELECT 'award_nominations' AS imported_table,count(*) AS reviewed_records_present FROM award_nominations t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='17f69ed8-4170-572a-bdda-e9c0ff24f987' AND m.target_table='award_nominations' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'award_vote_runs' AS imported_table,count(*) AS reviewed_records_present FROM award_vote_runs t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='17f69ed8-4170-572a-bdda-e9c0ff24f987' AND m.target_table='award_vote_runs' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'honor_slots' AS imported_table,count(*) AS reviewed_records_present FROM honor_slots t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='17f69ed8-4170-572a-bdda-e9c0ff24f987' AND m.target_table='honor_slots' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'honor_selections' AS imported_table,count(*) AS reviewed_records_present FROM honor_selections t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='17f69ed8-4170-572a-bdda-e9c0ff24f987' AND m.target_table='honor_selections' AND m.target_id=CAST(t.slot_id AS TEXT));
